rtk proxy env PATH="$PWD/.venv/bin:$PATH" .venv/bin/python -c 'import ast, subprocess, sys
owners=(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)
def norm(ref,path):
 source=subprocess.check_output(["git","show",f"{ref}:{path}"],text=True)
 tree=ast.parse(source,type_comments=True)
 for node in ast.walk(tree):
  if isinstance(node,owners) and node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):
   node.body=node.body[1:]
 for item in tree.type_ignores:
  item.lineno=0
 return ast.dump(tree,include_attributes=False)
bad=[p for p in sys.argv[1:] if norm("HEAD^",p)!=norm("HEAD",p)]
assert not bad,f"normalized AST changed: {bad}"' tests/unit/store/test_git_outcome.py tests/unit/store/test_merge_recovery.py tests/unit/store/test_stamped_lock.py tests/unit/store/test_store_paths.py tests/unit/store/test_windows_exclusive_leg.py
